// Reads all rows from the 'Recipe Queue' sheet. Every meal type (including
// Snack) works the same way now: a slot only runs today if the client has
// queued a PENDING idea for it. Nothing is invented - if he hasn't added
// anything for a slot, that slot is simply skipped, even if that means
// nothing gets published today at all.
const rows = $input.all().map(i => i.json);
const pending = rows.filter(r => (r.status || '').toString().toLowerCase() === 'pending');

const mealTypes = ['Breakfast', 'Lunch', 'Dinner', 'Snack'];
const batch = [];

for (const mealType of mealTypes) {
  const match = pending.find(r => (r.meal_type || '').toLowerCase() === mealType.toLowerCase());
  if (match) {
    batch.push({
      json: {
        meal_type: mealType,
        recipe_idea: match.recipe_idea,
        sheet_row_number: match.row_number
      }
    });
  }
}

return batch;

