// Stash the REAL resume URL n8n generates for this execution (includes
// a security token - do NOT try to rebuild this URL manually, it will
// 401). The Wait node right after this one is what actually creates the
// listener; this value is only valid because this Code node runs in the
// same execution, right before the Wait node.
const staticData = $getWorkflowStaticData('global');
staticData.pendingResumeUrl = $execution.resumeUrl;
staticData.pendingResumeAt = new Date().toISOString();
return $input.all();

const staticData = $getWorkflowStaticData('global');
const resumeUrl = staticData.pendingResumeUrl;
const chatId = String($json.message?.chat?.id || '');
const messageText = $json.message?.text || '';

const isRightChat = chatId === '1017116393';
const hasPending = !!resumeUrl && isRightChat;

return {
  json: {
    hasPending,
    resumeUrl: hasPending ? resumeUrl : null,
    messageText
  }
};

const staticData = $getWorkflowStaticData('global');
delete staticData.pendingResumeUrl;
delete staticData.pendingResumeAt;
return $input.all();

// No reply arrived before the 24h limit on "Wait For Reply" ran out.
// Clear the pending-review flag so a later, unrelated Telegram message
// doesn't try to resume this execution again (it isn't waiting any more).
const staticData = $getWorkflowStaticData('global');
delete staticData.pendingResumeUrl;
delete staticData.pendingResumeAt;
return $input.all();
